import io.xeros.*;import io.xeros.content.combat.*;import io.xeros.content.combat.core.*;import io.xeros.content.combat.formula.rework.*;import io.xeros.model.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;
public class Salamander69Check{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();for(int id:new int[]{10146,10147,10148,10149})for(int style=0;style<3;style++){Player p=WeaponsEquipment69Check.actor();p.setSpellId(-1);p.autocasting=false;p.playerEquipment[3]=id;p.playerEquipmentN[3]=1;p.playerEquipment[13]=Salamanders.ammo(id);p.playerEquipmentN[13]=1;p.getCombatConfigs().setAttackStyle(style);NPC n=CombatMagicPaymentCheck.target(p);BossRoutesCheck.at(p,n.getX()-1,n.getY(),n.getHeight());p.attacking.attackEntity(n);ok(!p.getDamageQueue().getQueue().isEmpty()&&p.playerEquipmentN[13]==0,"Salamander attack/tar "+id+" mode="+style);CombatType expected=style==0?CombatType.MELEE:style==1?CombatType.RANGE:CombatType.MAGE;ok(p.getDamageQueue().getQueue().peek().getCombatType()==expected,"Salamander damage type");int count=p.getDamageQueue().getQueue().size();p.attackTimer=0;p.attacking.attackEntity(n);ok(p.getDamageQueue().getQueue().size()==count,"Free salamander without tar");n.unregisterInstant();ToaSoloPlayableCheck.clear(p);}System.out.println("FOUR_SALAMANDERS_TWELVE_NATIVE_ATTACK_MODES_MAGIC_FORMULA_LAST_TAR_AND_EMPTY_GUARDS_PASS");System.exit(0);}}
